import{_ as t,o,c as a,ae as i}from"./chunks/framework.B2ul6ABY.js";const h=JSON.parse('{"title":"Executor Workspace Tooling Remediation Plan","description":"","frontmatter":{},"headers":[],"relativePath":"historical/2026-05-remediation-dossiers/executor-workspace-tooling-remediation-plan.md","filePath":"historical/2026-05-remediation-dossiers/executor-workspace-tooling-remediation-plan.md"}'),r={name:"historical/2026-05-remediation-dossiers/executor-workspace-tooling-remediation-plan.md"};function l(s,e,c,n,d,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<blockquote><p><strong>Historical/Audit Artifact — Not Current Operator Instructions</strong><br> This page records a remediation plan from an earlier stage. It is not authoritative for current Saivage v3 behavior unless a current active doc explicitly revalidates it against current source and tests.</p></blockquote><h1 id="executor-workspace-tooling-remediation-plan" tabindex="-1">Executor Workspace Tooling Remediation Plan <a class="header-anchor" href="#executor-workspace-tooling-remediation-plan" aria-label="Permalink to &quot;Executor Workspace Tooling Remediation Plan&quot;">​</a></h1><p>Date: 2026-05-15</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Fix the the target project recreation failure at the execution architecture level, not by manually creating missing files or patching the failed card. Saivage executors must have a real project-scoped way to inspect files, write files, and run verification commands in the project root.</p><h2 id="plan" tabindex="-1">Plan <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;Plan&quot;">​</a></h2><h3 id="_1-add-native-workspace-tools" tabindex="-1">1. Add Native Workspace Tools <a class="header-anchor" href="#_1-add-native-workspace-tools" aria-label="Permalink to &quot;1. Add Native Workspace Tools&quot;">​</a></h3><p>Create a first-class workspace tool module for real agent execution:</p><ul><li><code>list_project_files</code> lists project files while omitting Saivage internals.</li><li><code>read_project_file</code> reads files safely through existing project-root containment and secret-redaction logic.</li><li><code>write_project_file</code> writes project files atomically while blocking <code>.saivage</code> and <code>.saivage-work</code> state mutation.</li><li><code>run_project_command</code> runs commands through the existing process runner with project-root environment and captured logs.</li></ul><p>Acceptance criteria:</p><ul><li>Tools resolve paths inside the active <code>projectRoot</code>.</li><li>Writes outside the project root are rejected.</li><li>Saivage credential/runtime state cannot be modified through workspace tools.</li><li>Command output is captured and returned to the agent.</li></ul><h3 id="_2-wire-workspace-tools-into-agentadapter" tabindex="-1">2. Wire Workspace Tools Into AgentAdapter <a class="header-anchor" href="#_2-wire-workspace-tools-into-agentadapter" aria-label="Permalink to &quot;2. Wire Workspace Tools Into AgentAdapter&quot;">​</a></h3><p>Expose the workspace tools as normal function tools to planner, executor, and reviewer roles, with write and command tools restricted to executors.</p><p>Acceptance criteria:</p><ul><li>The executor sees the workspace tools in its function-tool list.</li><li><code>processToolCall()</code> executes workspace tools directly against <code>AgentAdapter.projectRoot</code>.</li><li>Tool errors are returned as tool errors instead of being hallucinated as successful work.</li></ul><h3 id="_3-preserve-provider-tool-call-identity" tabindex="-1">3. Preserve Provider Tool Call Identity <a class="header-anchor" href="#_3-preserve-provider-tool-call-identity" aria-label="Permalink to &quot;3. Preserve Provider Tool Call Identity&quot;">​</a></h3><p>Persist <code>tool_call_id</code> on agent messages and serialize tool-call messages correctly for both OpenAI-compatible chat completions and OpenAI Codex responses.</p><p>Acceptance criteria:</p><ul><li>Tool results reference the original provider call ID.</li><li>Persisted assistant tool-call messages can be replayed into follow-up model calls.</li><li>OpenAI Codex receives tools instead of having them stripped by the adapter.</li></ul><h3 id="_4-update-executor-instructions" tabindex="-1">4. Update Executor Instructions <a class="header-anchor" href="#_4-update-executor-instructions" aria-label="Permalink to &quot;4. Update Executor Instructions&quot;">​</a></h3><p>Make the executor prompt explicit that filesystem and command work must go through <code>list_project_files</code>, <code>read_project_file</code>, <code>write_project_file</code>, and <code>run_project_command</code>, and that it must not claim success unless tool calls succeeded.</p><p>Acceptance criteria:</p><ul><li>The system prompt matches the real tool contract.</li><li>Agents have proper context about how to perform concrete work.</li></ul><h3 id="_5-regression-tests" tabindex="-1">5. Regression Tests <a class="header-anchor" href="#_5-regression-tests" aria-label="Permalink to &quot;5. Regression Tests&quot;">​</a></h3><p>Add focused tests for the workspace tools and update existing tool-surface tests.</p><p>Acceptance criteria:</p><ul><li>Workspace tools can list, read, write, and run commands in a temp project.</li><li>Workspace tools reject path escapes and Saivage internal writes.</li><li>Existing load-skill and MCP tool tests pass with the expanded tool surface.</li><li>Typecheck passes.</li></ul><h3 id="_6-live-recreation-validation" tabindex="-1">6. Live Recreation Validation <a class="header-anchor" href="#_6-live-recreation-validation" aria-label="Permalink to &quot;6. Live Recreation Validation&quot;">​</a></h3><p>After implementation and build:</p><ul><li>Rebuild Saivage v3.</li><li>Refresh the live LXC installation from the rebuilt package.</li><li>Reset <code>target-project</code> again, preserving only <code>.saivage</code> credentials and required configuration.</li><li>Recreate the clean target objective.</li><li>Restart the live service.</li><li>Watch cards and runtime events until project files are actually created under <code>/work/target-project</code> and visible from the host project root.</li></ul><p>If the recreation still fails, repeat the debugging loop from the new failure evidence rather than manually filling the workspace.</p>',31)])])}const m=t(r,[["render",l]]);export{h as __pageData,m as default};
